import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"38、【睽】 兌下離上","description":"周易闡真 - 38、【睽】 兌下離上","frontmatter":{"title":"38、【睽】 兌下離上","description":"周易闡真 - 38、【睽】 兌下離上"},"headers":[],"relativePath":"classics/chanzhen/039.md","filePath":"classics/chanzhen/039.md"}'),s={name:"classics/chanzhen/039.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：睽，火動而上，澤動而下。二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛，是以小事吉。天地睽而其事同也。男女睽而其志通也。萬物睽而其事類也，睽之時用大矣哉！</p></blockquote><h1 id="_38、【睽】-兌下離上" tabindex="-1">38、【睽】 兌下離上 <a class="header-anchor" href="#_38、【睽】-兌下離上" aria-label="Permalink to “38、【睽】 兌下離上”">​</a></h1><p>初九：悔亡。喪馬勿逐，自復。見惡人，無咎。</p><p>九二：遇主於巷，無咎。</p><p>六三：見輿曳其牛，掣其人，天且劓。無初有終。</p><p>九四：睽孤。遇元夫，交孚，厲，無咎。</p><p>六五：悔亡，厥宗噬膚，往何咎？</p><p>上九：睽孤。見豕負塗，載鬼一車。先張之弧，後說之弧。匪寇婚媾，往遇雨則吉。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：上火下澤，睽。君子以同而異。</p><p>睽者，彼此不合也。上離火，下兌澤，是上火下澤也。火性上炎，澤水下潤，火在上而不能燻澤，澤在下而不能濟火，火澤同處，而異其性，睽之象也，</p><p>君子有見於此，知修道者不可不同乎人，而亦不可過同乎人。不同，則驚愚駭俗，取人嫌疑；過同，則隨風揚波，落於塵情。以是同中而有異焉。效澤之浸物，混俗和光，物來順應，方圓不拘，而無物不同；法火之照物，邪正分明，應物不迷，內有主宰，而操守大異。外同而內不同，內異而外不異。故能大同乎人，而亦大異乎人。外同者，依世法也；內異者，修道法也。所謂“修行混俗且和光，圓即圓兮方即方，顯晦逆從人莫測，教人爭得見行藏”者，是也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>曳，以制反。掣，音徹。弧，音胡。說，音脫。</p><p>睽者，彼此相違之義。卦德上離明，下兌悅，悅生於內，明用於外，悅非所悅，明非所明，悅明不當，故謂睽。此陰陽相隔，和緩調理之卦，承上明夷而來。明夷者，真明有昧之義。真明有昧，假明即出，識神用事，順其所欲，明於外而不明於內，性亂命搖，與道相隔，此睽之所由來也。然睽則睽矣，又有致合之道，特以明雖在外，若能虛其心，可以返明於內；欲雖起內，若能實其腹，可以掃欲於外。明返欲掃，神定情忘，則陰陽隔礙潛通，睽者亦可以致合，故小事吉也。</p><p>小事者，陰之事。人心用事已久，道心埋沒，大事已去，今欲致合，必先去人心而後生道心，道心復後，大事方吉。正在睽中，求其人心不壞，其事足矣。安敢望其大事之吉乎？試就小事吉者論之。</p><p>初九，在睽之初，道心方去，人心方來，若能剛而守正，不為人心所惑，道心自復，有悔者可以悔亡，如喪馬勿逐自復也。然必見惡人無咎者，惡人即人心，人心俱有五賊，足以敗道。不見人心，不知五賊作禍，見人心而順其所欲，漸次導引，五賊不得張狂，所以避害耳。此濟睽於方睽之時也。</p><p>九二，當陰陽正睽之時，邪氣盛而正氣弱，道心未易相遇。然剛以柔用，從小道中進步，借人心生道心，如遇主於巷，本有咎者，即能無咎。此濟睽於正盛之時也。</p><p>六三，愚而自用，順其所欲，如輿曳而牛掣也。不悅於內而悅於外，未得於彼，早失於己，如天頭而劓鼻也。如此之人，務外傷內，認假失真，到頭一著，窮無所歸，始悔自錯，故無初有終也。但不能悔於初，而悔於終，悔之無益。此不睽而自致其睽也。</p><p>九四，陽在陰中，道心為人心所陷，人心惟危，道心惟微，孤陽無依，是睽孤也。然道心雖微，若能敏而好學，不恥下問，交孚抱道之君子，彼此資益，人心日去，道心日增，久之人心化，道心存，陰陽混合，孤者可以不孤，有咎者可以無咎。此以尊交卑、能濟其睽也。</p><p>六五，柔順虛心，居二陽之中，既明其我家純陰，又明其他家有陽，虛人心而求道心，本有悔者，而悔可以亡矣。</p><p>夫道心者，人心之宗厥，取道心之宗，點化人心之假，如噬膚之易，以是往而行道，有何睽之咎乎?此以虛求實、能濟其睽也。</p><p>上九，處睽之極，道心埋沒已久，人不反顧，是睽孤也。道心埋沒，人心用事，習染成性，疑慮百出，如豕負塗，載鬼一車矣。若欲複道心，須先明人心，但明之貴於見之，見豕見鬼，實見的人心為害甚大。既能見的，即能明的，先不明而用心，如先張之弧也；後能明而複道心，如後說之弧也。無人心而不見道心，無道心而難知人心，借人心複道心。</p><p>人心雖罪之魁，亦功之首，匪寇而實婚媾也。人心既見，道心即復，於是虛人心，振道心，往而濟睽，則陰陽和合，如遇其雨，洗去一切舊染之汙，仍是當年圓成無虧之物，其吉為何如乎！此睽終必合，乘時而濟睽也。</p><p>六爻俱有睽而致合之道，僅得免其陰陽不睽，而不能陰陽有濟，故《彖》曰：“小事吉。”然小事能吉，大事即能吉，睽終而合，陰陽相通，至此而求，大事未有不致吉者。修道者，可不先求其小事之吉乎？</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
